package net.hawthorn.dndsheets.client;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.mojang.blaze3d.platform.NativeImage;
import net.hawthorn.dndsheets.DndsheetsMod;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.texture.DynamicTexture;
import net.minecraft.client.renderer.texture.MissingTextureAtlasSprite;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.packs.resources.ResourceManager;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * <p>Colours an archetype's mask texture into a variant, once, on the client. An archetype ships ONE
 * {@code textures/entity/<model>/mask.png} (per pixel: which colour role it is, how much of the dark colour to mix in, a
 * highlight amount) and one {@code variants.json} of palettes; the first time a variant is drawn this paints it into a
 * {@link DynamicTexture} and caches it. So a dragon colour is one line of JSON, not one more PNG, and a monster may
 * even ask for a raw {@code "#RRGGBB"} variant that derives its palette from that colour.</p>
 *
 * <p>Mask encoding (RGBA, written by {@code tools/blockbench/mobs/mobkit.py}): R = mix toward {@code dark},
 * G = role * 40 (base, dark, belly, horn, membrane, eye), B = whiten, A = 255 painted / 0 empty.</p>
 */
public final class MonsterTextures {
	private static final String[] ROLES = {"base", "dark", "belly", "horn", "membrane", "eye"};
	private static final Map<String, ResourceLocation> CACHE = new HashMap<>();

	private MonsterTextures() {
	}

	public static ResourceLocation get(String model, String variant) {
		return CACHE.computeIfAbsent(model + "/" + variant, key -> build(model, variant));
	}

	/** Called on every resource reload: palettes or masks may have changed. */
	public static void clear() {
		CACHE.values().forEach(location -> Minecraft.getInstance().getTextureManager().release(location));
		CACHE.clear();
	}

	private static ResourceLocation build(String model, String variant) {
		try {
			ResourceManager resources = Minecraft.getInstance().getResourceManager();
			int[][] palette = palette(resources, model, variant);
			ResourceLocation maskLocation = new ResourceLocation(DndsheetsMod.MODID, "textures/entity/" + model + "/mask.png");
			try (InputStream in = resources.open(maskLocation); NativeImage mask = NativeImage.read(in)) {
				NativeImage out = new NativeImage(mask.getWidth(), mask.getHeight(), false);
				for (int y = 0; y < mask.getHeight(); y++) {
					for (int x = 0; x < mask.getWidth(); x++) {
						out.setPixelRGBA(x, y, colour(mask.getPixelRGBA(x, y), palette));
					}
				}
				ResourceLocation id = new ResourceLocation(DndsheetsMod.MODID,
					"dynamic/" + model + "/" + variant.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9._-]", "_"));
				Minecraft.getInstance().getTextureManager().register(id, new DynamicTexture(out));
				return id;
			}
		} catch (Exception e) {
			DndsheetsMod.LOGGER.warn("dndsheets: cannot colour {}/{} ({}); drawing the missing texture.", model, variant, e.toString());
			return MissingTextureAtlasSprite.getLocation();
		}
	}

	/** ABGR in, ABGR out (NativeImage's byte order). */
	private static int colour(int abgr, int[][] palette) {
		int alpha = abgr >>> 24;
		if (alpha == 0) return 0;
		float dark = (abgr & 0xFF) / 255f;
		int role = Math.min(((abgr >> 8) & 0xFF) / 40, ROLES.length - 1);
		float white = ((abgr >> 16) & 0xFF) / 255f;
		int[] base = palette[role], shade = palette[1];
		int r = mix(mix(base[0], shade[0], dark), 255, white), g = mix(mix(base[1], shade[1], dark), 255, white), b = mix(mix(base[2], shade[2], dark), 255, white);
		return (255 << 24) | (b << 16) | (g << 8) | r;
	}

	private static int mix(int a, int b, float t) {
		return Math.max(0, Math.min(255, Math.round(a + (b - a) * t)));
	}

	private static int[][] palette(ResourceManager resources, String model, String variant) throws Exception {
		if (variant.startsWith("#")) return derived(Integer.parseInt(variant.substring(1), 16));
		ResourceLocation file = new ResourceLocation(DndsheetsMod.MODID, "textures/entity/" + model + "/variants.json");
		try (InputStream in = resources.open(file)) {
			JsonObject all = JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
			JsonObject one = all.has(variant) ? all.getAsJsonObject(variant) : all.getAsJsonObject(all.keySet().iterator().next());
			int[][] palette = new int[ROLES.length][];
			for (int i = 0; i < ROLES.length; i++) {
				JsonArray rgb = one.getAsJsonArray(ROLES[i]);
				palette[i] = new int[] {rgb.get(0).getAsInt(), rgb.get(1).getAsInt(), rgb.get(2).getAsInt()};
			}
			return palette;
		}
	}

	/** A palette from a single colour: darker shade, paler belly and horn, a warm eye. */
	private static int[][] derived(int rgb) {
		int[] base = {(rgb >> 16) & 0xFF, (rgb >> 8) & 0xFF, rgb & 0xFF};
		return new int[][] {base, scale(base, 0.6f), toward(base, 0.55f), toward(base, 0.75f), scale(base, 0.85f), {255, 228, 90}};
	}

	private static int[] scale(int[] c, float k) {
		return new int[] {Math.round(c[0] * k), Math.round(c[1] * k), Math.round(c[2] * k)};
	}

	private static int[] toward(int[] c, float t) {
		return new int[] {mix(c[0], 255, t), mix(c[1], 255, t), mix(c[2], 255, t)};
	}
}

"""Shared kit for the creature archetypes: a bone/cube description -> .bbmodel (geckolib_model) -> Bedrock geo.json,
ONE painted mask texture per archetype plus a variants.json of palettes, and the animation JSON.

The mask does not hold colours: each pixel stores a role (base, dark, belly, horn, membrane, eye), how much of the
dark colour to mix in, and a highlight amount. The client (MonsterTextures) colours it from a palette the first time a
variant is drawn, so a new colour is one line of JSON instead of one more PNG.
Mask encoding (RGBA): R = mix toward 'dark' (0..255), G = role * 40, B = whiten (0..255), A = 255 painted / 0 empty.

All art is generated from code, i.e. original (see CREDITS.md: no third-party creature art is used)."""
import base64, hashlib, json, os, struct, sys, zlib

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.dirname(HERE))
import bbmcp

REPO = os.path.abspath(os.path.join(HERE, '..', '..', '..'))
ASSETS = os.path.join(REPO, 'src', 'main', 'resources', 'assets', 'dndsheets')
ROLES = ['base', 'dark', 'belly', 'horn', 'membrane', 'eye']  # index * 40 = the mask's green channel


def png(w, h, px):
    raw = b''.join(b'\x00' + b''.join(bytes(px[y][x]) for x in range(w)) for y in range(h))

    def ch(t, d):
        c = struct.pack('>I', len(d)) + t + d
        return c + struct.pack('>I', zlib.crc32(t + d) & 0xffffffff)
    return b'\x89PNG\r\n\x1a\n' + ch(b'IHDR', struct.pack('>IIBBBBB', w, h, 8, 6, 0, 0, 0)) + ch(b'IDAT', zlib.compress(raw, 9)) + ch(b'IEND', b'')


def text(r):
    res = r.get('result', {})
    return '\n'.join(c.get('text', '') for c in res.get('content', [])) + ('  [ERROR]' if res.get('isError') or 'error' in r else '')


class Cube:
    def __init__(self, name, bone, a, b, role='base', uvkey=None):
        self.name, self.bone, self.a, self.b, self.role = name, bone, a, b, role
        self.uvkey = uvkey or name
        self.size = tuple(b[i] - a[i] for i in range(3))
        self.uv = None  # (u, v), set by pack()


def pack(cubes, tw, th):
    """Shelf-packs each distinct uvkey's box-UV net; cubes sharing a key (left/right copies) share the net."""
    placed, x, y, row = {}, 0, 0, 0
    for c in cubes:
        if c.uvkey not in placed:
            w, h, d = (int(v) for v in c.size)
            nw, nh = 2 * d + 2 * w, d + h
            if x + nw > tw:
                x, y, row = 0, y + row, 0
            assert y + nh <= th, 'texture %dx%d too small at %s' % (tw, th, c.name)
            placed[c.uvkey] = (x, y)
            x += nw
            row = max(row, nh)
        c.uv = placed[c.uvkey]
    return placed


def _noise(x, y, k):
    return hashlib.md5(('%d,%d,%s' % (x, y, k)).encode()).digest()[0] / 255.0


def mix(a, b, t):
    return tuple(int(a[i] + (b[i] - a[i]) * t) for i in range(3))


def pixels(cubes, tw, th, belly_roles=('base',)):
    """Per painted pixel: (role, dark mix 0..1, whiten 0..1). Scale lattice, lighter top, belly underneath."""
    px = [[None] * tw for _ in range(th)]
    done = set()
    for c in cubes:
        if c.uvkey in done:
            continue
        done.add(c.uvkey)
        w, h, d = (int(v) for v in c.size)
        u, v = c.uv
        faces = {'up': (u + d, v, w, d), 'down': (u + d + w, v, w, d), 'west': (u, v + d, d, h),
                 'north': (u + d, v + d, w, h), 'east': (u + d + w, v + d, d, h), 'south': (u + 2 * d + w, v + d, w, h)}
        role = 'horn' if c.role == 'claw' else c.role
        for face, (fx, fy, fw, fh) in faces.items():
            for j in range(fh):
                for i in range(fw):
                    n = _noise(fx + i, fy + j, role)
                    p = (role, 0.0, 0.0)
                    if role == 'base':
                        lattice = ((i + (j % 2) * 2) % 4 == 0 and j % 2 == 0)
                        p = ('base', 0.55 if lattice else 0.12 * n, 0.08 if face == 'up' else 0.0)
                        if face == 'down' or (face in ('north', 'south', 'east', 'west') and j >= fh * 0.7 and role in belly_roles):
                            p = ('belly', 0.15 * n + (0.25 if (i + j) % 4 == 0 else 0), 0.0)
                    elif role == 'membrane':
                        p = ('membrane', 0.5 if i % 4 == 0 else 0.1 * n, 0.0)
                    elif role == 'horn':
                        p = ('horn', 0.5 * (j / max(fh, 1)) + 0.1 * n, 0.0)
                    px[fy + j][fx + i] = p
    return px


def mask_png(px, tw, th):
    out = [[(0, 0, 0, 0)] * tw for _ in range(th)]
    for y in range(th):
        for x in range(tw):
            p = px[y][x]
            if p:
                out[y][x] = (int(p[1] * 255), ROLES.index(p[0]) * 40, int(p[2] * 255), 255)
    return png(tw, th, out)


def preview_png(px, tw, th, pal):
    """The same pixels coloured with one palette: what the .bbmodel shows and what the game will draw."""
    out = [[(0, 0, 0, 0)] * tw for _ in range(th)]
    for y in range(th):
        for x in range(tw):
            p = px[y][x]
            if p:
                col = mix(mix(pal[p[0]], pal['dark'], p[1]), (255, 255, 255), p[2])
                out[y][x] = col + (255,)
    return png(tw, th, out)


class Archetype:
    """name, bones [(name, parent, pivot, rotation)], cubes [Cube], palettes {variant: pal}, animations {key: {...}}."""
    tw = th = 128

    def __init__(self, name, bones, cubes, palettes, animations, belly_roles=('base',)):
        self.name, self.bones, self.cubes = name, bones, cubes
        self.palettes, self.animations, self.belly_roles = palettes, animations, belly_roles
        pack(cubes, self.tw, self.th)
        self.px = pixels(cubes, self.tw, self.th, belly_roles)

    def build(self, c, first_variant):
        bb = os.path.join(HERE, self.name + '.bbmodel')
        tex = preview_png(self.px, self.tw, self.th, self.palettes[first_variant])
        c.call('bbmodel_create', {'file': bb, 'format': 'geckolib_model', 'name': self.name, 'box_uv': True, 'overwrite': True,
                                  'resolution': {'width': self.tw, 'height': self.th}})
        ops = [{'op': 'add_texture', 'name': first_variant, 'source': 'data:image/png;base64,' + base64.b64encode(tex).decode(),
                'width': self.tw, 'height': self.th}]
        for name, parent, pivot, rot in self.bones:
            ops.append({'op': 'add_group', 'name': name, 'origin': pivot, 'rotation': rot, 'parent': parent})
        for cu in self.cubes:
            ops.append({'op': 'add_cube', 'name': cu.name, 'from': list(cu.a), 'to': list(cu.b), 'parent': cu.bone, 'box_uv': True,
                        'uv_offset': list(cu.uv), 'texture': first_variant})
        print(self.name, 'edit:', text(c.call('bbmodel_edit', {'file': bb, 'operations': ops}))[:160].replace(chr(10), ' '))
        v = text(c.call('bbmodel_validate', {'file': bb}))
        print(self.name, 'validate passed:', '"passed": true' in v, '' if '"passed": true' in v else v[:600])
        # The server only writes inside its workspace (tools/blockbench), so export there and copy into the assets.
        tmp = os.path.join(HERE, '..', 'out', self.name + '.geo.json')
        os.makedirs(os.path.dirname(tmp), exist_ok=True)
        print(self.name, 'export:', text(c.call('bbmodel_export_bedrock_geometry', {'file': bb, 'output': os.path.abspath(tmp), 'overwrite': True, 'identifier': 'geometry.' + self.name}))[:140].replace(chr(10), ' '))
        geo = os.path.join(ASSETS, 'geo', 'entity', self.name + '.geo.json')
        os.makedirs(os.path.dirname(geo), exist_ok=True)
        open(geo, 'w', newline=chr(10)).write(open(tmp, encoding='utf-8').read())

    def install_textures(self):
        d = os.path.join(ASSETS, 'textures', 'entity', self.name)
        os.makedirs(d, exist_ok=True)
        for f in os.listdir(d):  # the old one-PNG-per-variant files
            if f.endswith('.png'):
                os.remove(os.path.join(d, f))
        open(os.path.join(d, 'mask.png'), 'wb').write(mask_png(self.px, self.tw, self.th))
        variants = {v: {r: list(pal[r]) for r in ROLES} for v, pal in self.palettes.items()}
        open(os.path.join(d, 'variants.json'), 'w', newline=chr(10)).write(json.dumps(variants, indent=1) + chr(10))

    def install_animations(self):
        d = os.path.join(ASSETS, 'animations', 'entity')
        os.makedirs(d, exist_ok=True)
        out = {'format_version': '1.8.0', 'animations': self.animations}
        open(os.path.join(d, self.name + '.animation.json'), 'w', newline=chr(10)).write(json.dumps(out, indent=1) + chr(10))

    def run(self):
        c = bbmcp.Client()
        try:
            self.build(c, next(iter(self.palettes)))
        finally:
            c.close()
        self.install_textures()
        self.install_animations()
        print(self.name, 'installed:', len(self.cubes), 'cubes, 1 mask +', len(self.palettes), 'palettes,', len(self.animations), 'animations')


def keys(length, frames):
    """frames: {time: [x,y,z]} -> Bedrock keyframe dict with string times."""
    return {('%g' % t): list(v) for t, v in sorted(frames.items())}

package net.hawthorn.dndsheets.entity;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.network.syncher.EntityDataSerializers;
import net.minecraft.network.syncher.SynchedEntityData;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityDimensions;
import net.minecraft.world.entity.Pose;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.ai.attributes.AttributeSupplier;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.level.Level;
import software.bernie.geckolib.animatable.GeoEntity;
import software.bernie.geckolib.core.animatable.instance.AnimatableInstanceCache;
import software.bernie.geckolib.core.animation.AnimatableManager;
import software.bernie.geckolib.core.animation.AnimationController;
import software.bernie.geckolib.core.animation.AnimationState;
import software.bernie.geckolib.core.animation.RawAnimation;
import software.bernie.geckolib.core.object.PlayState;
import software.bernie.geckolib.util.GeckoLibUtil;

/**
 * <p>The mod's own creature: ONE entity type that wears any of the archetype models (dragon, goblinoid, ...).
 * Which one is decided by two synced strings, {@code model} (the archetype: where the geometry, animations and
 * texture folder live) and {@code variant} (which texture of that archetype: a dragon's colour). Adding an
 * archetype is therefore three resource files and one line in {@code monsters.json}, with no Java.</p>
 *
 * <p>A monster picks it with {@code "baseEntity": "dndsheets:monster_model"} plus {@code appearance.model} /
 * {@code appearance.variant}. Because it goes through {@code baseEntity}, a skin pack for another creature mod
 * ({@link net.hawthorn.dndsheets.MonsterSkins}) still wins when it applies: it just replaces that id.</p>
 *
 * <p>Animation names are the plain keys {@code idle, fly, attack, hurt, death} in every archetype's file, so the
 * Java never names an archetype. A missing animation is simply not played.</p>
 */
public class MonsterModelEntity extends PathfinderMob implements GeoEntity {
	public static final String DEFAULT_MODEL = "dragon";
	public static final String DEFAULT_VARIANT = "red";

	private static final EntityDataAccessor<String> MODEL = SynchedEntityData.defineId(MonsterModelEntity.class, EntityDataSerializers.STRING);
	private static final EntityDataAccessor<String> VARIANT = SynchedEntityData.defineId(MonsterModelEntity.class, EntityDataSerializers.STRING);
	private static final EntityDataAccessor<Boolean> BABY = SynchedEntityData.defineId(MonsterModelEntity.class, EntityDataSerializers.BOOLEAN);
	private static final EntityDataAccessor<Boolean> FLYING = SynchedEntityData.defineId(MonsterModelEntity.class, EntityDataSerializers.BOOLEAN);

	private final AnimatableInstanceCache cache = GeckoLibUtil.createInstanceCache(this);

	public MonsterModelEntity(EntityType<? extends MonsterModelEntity> type, Level level) {
		super(type, level);
		setPersistenceRequired(); //A placed monster is never "far away"; it despawns only when the DM removes it.
	}

	public static AttributeSupplier.Builder createAttributes() {
		//Real HP/AC live in the stat block and the dndsheets NBT tag, like for every monster; this is only so the entity is valid.
		return Mob.createMobAttributes().add(Attributes.MAX_HEALTH, 20.0).add(Attributes.MOVEMENT_SPEED, 0.25);
	}

	@Override
	protected void defineSynchedData() {
		super.defineSynchedData();
		entityData.define(MODEL, DEFAULT_MODEL);
		entityData.define(VARIANT, DEFAULT_VARIANT);
		entityData.define(FLYING, false);
		entityData.define(BABY, false);
	}

	//"appearance.baby" (a dragon wyrmling): half size, hitbox included. Vanilla spells it isBaby()/setBaby() on Mob.
	@Override
	public boolean isBaby() {
		return entityData.get(BABY);
	}

	@Override
	public void setBaby(boolean baby) {
		entityData.set(BABY, baby);
		refreshDimensions();
	}

	@Override
	public EntityDimensions getDimensions(Pose pose) {
		return isBaby() ? super.getDimensions(pose).scale(0.5f) : super.getDimensions(pose);
	}

	public String getModel() {
		String model = entityData.get(MODEL);
		return model.isEmpty() ? DEFAULT_MODEL : model;
	}

	public String getVariant() {
		String variant = entityData.get(VARIANT);
		return variant.isEmpty() ? DEFAULT_VARIANT : variant;
	}

	public boolean isFlyingPose() {
		return entityData.get(FLYING);
	}

	/** Called by {@code MonsterRegistry.applyLooks}; null/blank keeps the default. */
	public void configure(String model, String variant, boolean flying) {
		if (model != null && !model.isBlank()) entityData.set(MODEL, model);
		if (variant != null && !variant.isBlank()) entityData.set(VARIANT, variant);
		entityData.set(FLYING, flying);
	}

	/** Plays a one-shot ("attack", "hurt") on whatever archetype this is; no-op on any other entity. */
	public static void play(Entity entity, String trigger) {
		if (entity instanceof MonsterModelEntity self && !self.level().isClientSide) self.triggerAnim("action", trigger);
	}

	@Override
	public void addAdditionalSaveData(CompoundTag tag) {
		super.addAdditionalSaveData(tag);
		tag.putString("Model", entityData.get(MODEL));
		tag.putString("Variant", entityData.get(VARIANT));
		tag.putBoolean("FlyingPose", isFlyingPose());
		tag.putBoolean("Baby", isBaby());
	}

	@Override
	public void readAdditionalSaveData(CompoundTag tag) {
		super.readAdditionalSaveData(tag);
		configure(tag.getString("Model"), tag.getString("Variant"), tag.getBoolean("FlyingPose"));
		setBaby(tag.getBoolean("Baby"));
	}

	@Override
	public boolean hurt(DamageSource source, float amount) {
		boolean hurt = super.hurt(source, amount);
		if (hurt && isAlive()) play(this, "hurt");
		return hurt;
	}

	@Override
	public void registerControllers(AnimatableManager.ControllerRegistrar controllers) {
		controllers.add(new AnimationController<>(this, "main", 5, this::mainAnimation));
		controllers.add(new AnimationController<>(this, "action", 0, state -> PlayState.STOP)
			.triggerableAnim("attack", RawAnimation.begin().thenPlay("attack"))
			.triggerableAnim("hurt", RawAnimation.begin().thenPlay("hurt")));
	}

	private PlayState mainAnimation(AnimationState<MonsterModelEntity> state) {
		if (isDeadOrDying()) return state.setAndContinue(RawAnimation.begin().thenPlayAndHold("death"));
		return state.setAndContinue(RawAnimation.begin().thenLoop(isFlyingPose() ? "fly" : "idle"));
	}

	@Override
	public AnimatableInstanceCache getAnimatableInstanceCache() {
		return cache;
	}
}

package net.hawthorn.dndsheets.client;

import com.mojang.blaze3d.vertex.PoseStack;
import net.hawthorn.dndsheets.DndsheetsMod;
import net.hawthorn.dndsheets.entity.MonsterModelEntity;
import net.hawthorn.dndsheets.init.DndsheetsModEntities;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.resources.ResourceLocation;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.client.event.EntityRenderersEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import software.bernie.geckolib.cache.object.BakedGeoModel;
import software.bernie.geckolib.model.GeoModel;
import software.bernie.geckolib.renderer.GeoEntityRenderer;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * <p>Draws {@link MonsterModelEntity}: one renderer for every archetype, the files chosen from the entity's synced
 * {@code model} / {@code variant}. Layout (all under {@code assets/dndsheets/}):
 * {@code geo/entity/<model>.geo.json}, {@code animations/entity/<model>.animation.json},
 * {@code textures/entity/<model>/mask.png} + {@code variants.json} (coloured on the client by {@link MonsterTextures}).</p>
 */
@Mod.EventBusSubscriber(modid = DndsheetsMod.MODID, bus = Mod.EventBusSubscriber.Bus.MOD, value = Dist.CLIENT)
public class MonsterModelRenderer extends GeoEntityRenderer<MonsterModelEntity> {
	public MonsterModelRenderer(EntityRendererProvider.Context context) {
		super(context, new Model());
		this.shadowRadius = 0.6f;
	}

	@Override
	protected float getDeathMaxRotation(MonsterModelEntity entity) {
		return 0; //The archetype's own "death" animation plays instead of the vanilla fall-over.
	}

	@Override
	public void scaleModelForRender(float widthScale, float heightScale, PoseStack poseStack, MonsterModelEntity entity,
			BakedGeoModel model, boolean isReRender, float partialTick, int packedLight, int packedOverlay) {
		float baby = entity.isBaby() ? 0.5f : 1f;
		super.scaleModelForRender(widthScale * baby, heightScale * baby, poseStack, entity, model, isReRender, partialTick, packedLight, packedOverlay);
	}

	//Palettes and masks may change with a resource pack: recolour on the next draw after every reload.
	@SubscribeEvent
	public static void reloadTextures(net.minecraftforge.client.event.RegisterClientReloadListenersEvent event) {
		event.registerReloadListener((net.minecraft.server.packs.resources.ResourceManagerReloadListener) manager -> MonsterTextures.clear());
	}

	@SubscribeEvent
	public static void register(EntityRenderersEvent.RegisterRenderers event) {
		event.registerEntityRenderer(DndsheetsModEntities.MONSTER_MODEL.get(), MonsterModelRenderer::new);
	}

	private static class Model extends GeoModel<MonsterModelEntity> {
		//Building a ResourceLocation per frame would allocate for nothing; a handful of distinct keys, so a plain map is enough.
		private final Map<String, ResourceLocation> cache = new ConcurrentHashMap<>();

		private ResourceLocation at(String path) {
			return cache.computeIfAbsent(path, p -> new ResourceLocation(DndsheetsMod.MODID, p));
		}

		@Override
		public ResourceLocation getModelResource(MonsterModelEntity entity) {
			return at("geo/entity/" + entity.getModel() + ".geo.json");
		}

		@Override
		public ResourceLocation getTextureResource(MonsterModelEntity entity) {
			return MonsterTextures.get(entity.getModel(), entity.getVariant());
		}

		@Override
		public ResourceLocation getAnimationResource(MonsterModelEntity entity) {
			return at("animations/entity/" + entity.getModel() + ".animation.json");
		}
	}
}

