31	public final class MonsterTextures {
32		private static final String[] ROLES = {"base", "dark", "belly", "horn", "membrane", "eye"};
33		private static final Map<String, ResourceLocation> CACHE = new HashMap<>();
34	
35		private MonsterTextures() {
36		}
