48		private static ResourceLocation build(String model, String variant) {
49			try {
50				ResourceManager resources = Minecraft.getInstance().getResourceManager();
51				int[][] palette = palette(resources, model, variant);
52				ResourceLocation maskLocation = new ResourceLocation(DndsheetsMod.MODID, "textures/entity/" + model + "/mask.png");
53				try (InputStream in = resources.open(maskLocation); NativeImage mask = NativeImage.read(in)) {
54					NativeImage out = new NativeImage(mask.getWidth(), mask.getHeight(), false);
55					for (int y = 0; y < mask.getHeight(); y++) {
56						for (int x = 0; x < mask.getWidth(); x++) {
57							out.setPixelRGBA(x, y, colour(mask.getPixelRGBA(x, y), palette));
58						}
59					}
60					ResourceLocation id = new ResourceLocation(DndsheetsMod.MODID,
61						"dynamic/" + model + "/" + variant.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9._-]", "_"));
62					Minecraft.getInstance().getTextureManager().register(id, new DynamicTexture(out));
63					return id;
64				}
65			} catch (Exception e) {
66				DndsheetsMod.LOGGER.warn("dndsheets: cannot colour {}/{} ({}); drawing the missing texture.", model, variant, e.toString());
67				return MissingTextureAtlasSprite.getLocation();
68			}
69		}
