71		/** ABGR in, ABGR out (NativeImage's byte order). */
72		private static int colour(int abgr, int[][] palette) {
73			int alpha = abgr >>> 24;
74			if (alpha == 0) return 0;
75			float dark = (abgr & 0xFF) / 255f;
76			int role = Math.min(((abgr >> 8) & 0xFF) / 40, ROLES.length - 1);
77			float white = ((abgr >> 16) & 0xFF) / 255f;
78			int[] base = palette[role], shade = palette[1];
79			int r = mix(mix(base[0], shade[0], dark), 255, white), g = mix(mix(base[1], shade[1], dark), 255, white), b = mix(mix(base[2], shade[2], dark), 255, white);
80			return (255 << 24) | (b << 16) | (g << 8) | r;
81		}
82	
83		private static int mix(int a, int b, float t) {
84			return Math.max(0, Math.min(255, Math.round(a + (b - a) * t)));
85		}
