87		private static int[][] palette(ResourceManager resources, String model, String variant) throws Exception {
88			if (variant.startsWith("#")) return derived(Integer.parseInt(variant.substring(1), 16));
89			ResourceLocation file = new ResourceLocation(DndsheetsMod.MODID, "textures/entity/" + model + "/variants.json");
90			try (InputStream in = resources.open(file)) {
91				JsonObject all = JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
92				JsonObject one = all.has(variant) ? all.getAsJsonObject(variant) : all.getAsJsonObject(all.keySet().iterator().next());
93				int[][] palette = new int[ROLES.length][];
94				for (int i = 0; i < ROLES.length; i++) {
95					JsonArray rgb = one.getAsJsonArray(ROLES[i]);
96					palette[i] = new int[] {rgb.get(0).getAsInt(), rgb.get(1).getAsInt(), rgb.get(2).getAsInt()};
97				}
98				return palette;
99			}
100		}
101	
102		/** A palette from a single colour: darker shade, paler belly and horn, a warm eye. */
103		private static int[][] derived(int rgb) {
104			int[] base = {(rgb >> 16) & 0xFF, (rgb >> 8) & 0xFF, rgb & 0xFF};
105			return new int[][] {base, scale(base, 0.6f), toward(base, 0.55f), toward(base, 0.75f), scale(base, 0.85f), {255, 228, 90}};
106		}
107	
108		private static int[] scale(int[] c, float k) {
109			return new int[] {Math.round(c[0] * k), Math.round(c[1] * k), Math.round(c[2] * k)};
110		}
111	
112		private static int[] toward(int[] c, float t) {
113			return new int[] {mix(c[0], 255, t), mix(c[1], 255, t), mix(c[2], 255, t)};
114		}
