229		 * <p>Changes ONLY the model of an already-registered monster, leaving its rules intact. Used by
230		 * {@link MonsterSkins} so a dragon can become another mod's dragon without touching its stat block.</p>
231		 *
232		 * <p>It checks that the entity exists before changing anything, and that check is the whole safety
233		 * net for the idea: a wrong id in an appearance pack leaves the vanilla model as it was instead of
234		 * degrading a monster that worked. Without it, a typo would turn a vindicator into a zombie.</p>
235		 *
236		 * @return {@code true} if it was applied.
237		 */
238		public static boolean reskin(String id, String entityId) {
239			MonsterStatBlock block = REGISTRY.get(id);
240			if (block == null) return false;
241			ResourceLocation loc = ResourceLocation.tryParse(entityId);
242			if (loc == null || !ForgeRegistries.ENTITY_TYPES.containsKey(loc)) return false;
243	
244			REGISTRY.replace(new MonsterStatBlock(block.id(), block.name(), entityId, block.ac(), block.maxHp(),
245				block.abilities(), block.proficiencyBonus(), block.attacks(), block.spells(), block.damageAffinities(),
246				block.nonmagicalAffinities(), block.type(), block.legendaryResistances(), block.legendaryActions(),
247				block.attacksPerTurn(), block.size(), block.appearance(), block.keepsOwnAi(), block.ownClock(), block.flies(), block.lairActions(), block.magicResistance()));
248			return true;
