756		@Nullable
757		public static Entity spawnAt(ServerLevel level, double x, double y, double z, String monsterId,
758				java.util.function.Consumer<Entity> configure) {
759			MonsterStatBlock block = get(monsterId);
760			if (block == null) return null;
761	
762			ResourceLocation entityLoc = ResourceLocation.tryParse(block.baseEntityId());
763			EntityType<?> type = entityLoc != null ? ForgeRegistries.ENTITY_TYPES.getValue(entityLoc) : null;
764			if (type == null) {
765				//An unknown id is almost always an addon pointing at an entity from ANOTHER mod that isn't
766				//installed. Returning null left the DM with a command that did nothing and no explanation. A
767				//zombie with the right name and stats is a playable token; nothing is not.
768				DndsheetsMod.LOGGER.warn("dndsheets: monster \"{}\" asks for entity \"{}\", which does not exist (is the mod that provides it missing?). Using a zombie.",
769					monsterId, block.baseEntityId());
770				type = EntityType.ZOMBIE;
771			}
772	
773			Entity entity = type.create(level);
774			if (entity == null) return null;
775	
776			entity.moveTo(x, y, z, 0, 0);
777			entity.setCustomName(ContentNames.of(block.name()));
778			entity.setCustomNameVisible(true);
779			//Frozen unless the block asks otherwise with "ai": true; see keepsOwnAi. A boss with its own
780			//clock needs it switched on by definition: it moves on its own throughout the combat.
781			if (entity instanceof Mob mob) mob.setNoAi(!block.keepsOwnAi() && !block.ownClock());
782			applyLooks(entity, block);
783			//Difficulty scaling, same method as Combatant.MonsterCombatant.maxHp(), so the monster
784			//is born with the HP its own bar is going to announce, instead of appearing "already hit" on easy or
785			//"overhealed" on hard.
786			tagAsMonster(entity, monsterId, Config.scaleMonsterMaxHp(block.maxHp()));
787			if (configure != null) configure.accept(entity);
788	
789			level.addFreshEntity(entity);
790	
791			//Without this, NoAI + yaw 0 makes every summoned monster always face north.
792			//They are oriented toward the nearest player so it's clear who they are threatening.
793			Player nearest = level.getNearestPlayer(entity, 30);
794			if (nearest != null) faceTarget(entity, nearest);

