    out = {}
    for bone, _, w in R.posed_cubes(model, anim, t):
        out.setdefault(bone, []).append(aabb(w))
    return out


def solid_parent(model, bone):
    p = model.bones[bone]['parent']
    while p and not model.bones[p]['cubes']:
